#!/usr/bin/env python3
"""One-time Research & Publication import script. Run on Render Shell."""
import os, json, gzip, base64, psycopg2, psycopg2.extras
from datetime import datetime

DATA = """"""

def main():
    rows = json.loads(gzip.decompress(base64.b64decode(DATA)))
    conn = psycopg2.connect(os.environ["DATABASE_URL"], cursor_factory=psycopg2.extras.RealDictCursor)
    cur = conn.cursor()
    imported = updated = skipped = 0
    for row in rows:
        candidate = row.get("Enter Candidate Name", "").strip()
        if not candidate:
            skipped += 1
            continue
        parts = candidate.rsplit(" - ", 1)
        reg_num = parts[1].strip() if len(parts) == 2 else ""
        if not reg_num:
            skipped += 1
            continue
        cur.execute("SELECT registration_number FROM plab_clients WHERE registration_number = %s", (reg_num,))
        if not cur.fetchone():
            skipped += 1
            continue
        g = lambda k: row.get(k, "").strip()
        def parse_date(v):
            v = v.strip() if v else ""
            if not v:
                return ""
            for fmt in ("%Y-%m-%d", "%d-%b-%Y", "%d/%m/%Y", "%Y-%m-%d %H:%M:%S"):
                try:
                    return datetime.strptime(v, fmt).strftime("%Y-%m-%d")
                except ValueError:
                    continue
            return v
        research_status = g("Research Status")
        research_topic = g("Research Topic")
        published_copy = g("Published Copy")
        start_date = parse_date(g("Research Start Date"))
        end_date = parse_date(g("Research End Date"))
        provider = g("Research Provider")
        mobile = g("Mobile Number")
        email = g("Candidate Email")
        batch = g("Research Batch")
        journal = g("Published Journal Name")
        author_pos = g("Author Position")
        notes = g("Additional Notes")

        cur.execute(
            "SELECT id FROM ops_research_publication WHERE registration_number = %s AND COALESCE(research_provider,'') = %s AND COALESCE(research_start_date,'') = %s",
            (reg_num, provider, start_date)
        )
        exists = cur.fetchone()
        if exists:
            cur.execute("""UPDATE ops_research_publication SET
                research_status=%s, research_topic=%s, published_copy=%s,
                research_end_date=%s, published_journal_name=%s, author_position=%s,
                research_batch=%s, mobile_number=%s, candidate_email=%s,
                additional_notes=%s WHERE id=%s""", (
                research_status, research_topic, published_copy,
                end_date, journal, author_pos,
                batch, mobile, email, notes, exists["id"]
            ))
            updated += 1
        else:
            cur.execute("""INSERT INTO ops_research_publication (
                registration_number, research_status, research_topic, published_copy,
                research_start_date, research_end_date, research_provider,
                published_journal_name, author_position, research_batch,
                mobile_number, candidate_email, additional_notes, created_by
            ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", (
                reg_num, research_status, research_topic, published_copy,
                start_date, end_date, provider,
                journal, author_pos, batch,
                mobile, email, notes, 0
            ))
            imported += 1
    conn.commit()
    cur.close()
    conn.close()
    print(f"Research: {imported} new, {updated} updated, {skipped} skipped")
    print(f"Total Research: {imported + updated + skipped}")

if __name__ == "__main__":
    main()
